import sys, importlib, json
sys.path.insert(0, 'scripts')
spec = importlib.util.spec_from_file_location('preseed', 'scripts/preseed_session_plan.py')
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

# Let me trace through the function manually
assessment = 'No known current bug matched this assessment.'
current = mod.current_evidence_text(assessment)
print('current_evidence_text:', repr(current))
lower = (current if current.strip() else assessment).lower()
print('lower:', repr(lower))
metrics = mod.numeric_metrics(lower)
print('metrics:', metrics)
lifecycle_metrics_present = mod.has_lifecycle_metrics(metrics)
print('lifecycle_metrics_present:', lifecycle_metrics_present)
analysis_only_active = mod._has_analysis_only_pressure(metrics)
print('analysis_only_active:', analysis_only_active)

candidates = []
for task in mod.TASKS:
    if not any(key in lower for key in task['keys']):
        continue

    # Check cold-start block
    if (
        task['title'] == 'Improve cold-start state failure diagnostics'
        and not mod._has_cold_start_failure_evidence(lower)
    ):
        continue

    if any(key in lower for key in task.get('reject_keys', ())):
        continue

    if task['title'] == mod.ANALYSIS_ONLY_TASK_TITLE and (mod._analysis_only_seed_recently_blocked(lower) or analysis_only_active):
        continue

    if mod._has_protected_files(task):
        continue

    if not mod._candidate_files_exist(task):
        continue

    if analysis_only_active and mod._task_file_count(task) > 3:
        continue

    if task['title'] == mod.LIFECYCLE_TASK_TITLE and lifecycle_metrics_present:
        if analysis_only_active:
            continue
        if not mod.has_actionable_lifecycle_gap(metrics):
            continue
        candidates.append(task)
        continue

    if task['title'] == mod.SEARCH_FRICTION_TASK_TITLE:
        if not mod.has_actionable_search_friction(lower):
            continue
        candidates.append(task)
        continue

    candidates.append(task)

print(f'candidates count: {len(candidates)}')
for c in candidates:
    print(f'  candidate: {c[\"title\"]}')

# Now trace the final logic
if analysis_only_active:
    # Stable sort: prefer src files
    candidates.sort(key=lambda c: not mod._has_src_files(c))

success_rate = metrics.get('task_success_rate', 1)
if success_rate == 0:
    candidates.sort(key=lambda c: mod._task_file_count(c))

for candidate in candidates:
    contradicted, reason = mod.check_task_contradiction(candidate, assessment)
    if not contradicted:
        print('Returning non-contradicted:', candidate['title'])
        break
else:
    print('All contradicted or no candidates')
    if candidates:
        print('Returning first contradicted:', candidates[0]['title'])
    elif analysis_only_active:
        print('Would return healthy_codebase_fallback')
    else:
        print('Would return self-referential fallback')
